import{_ as e,o as i,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"版本迁移、发布与回滚","description":"管理代码、API、数据、工作流、Prompt、模型与索引的兼容版本，用扩展-迁移-收缩和渐进发布实现可回滚变更。","frontmatter":{"title":"版本迁移、发布与回滚","description":"管理代码、API、数据、工作流、Prompt、模型与索引的兼容版本，用扩展-迁移-收缩和渐进发布实现可回滚变更。","verified_at":"2026-07-31","source":["https://kubernetes.io/docs/concepts/workloads/controllers/deployment/","https://sre.google/sre-book/release-engineering/","https://sre.google/sre-book/canarying-releases/","https://semver.org/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/quality/deployment-reliability/version-migration-release-rollback.md","filePath":"py-agent/quality/deployment-reliability/version-migration-release-rollback.md","lastUpdated":1785589115000}'),r={name:"py-agent/quality/deployment-reliability/version-migration-release-rollback.md"};function n(l,a,h,o,p,d){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="版本迁移、发布与回滚" tabindex="-1">版本迁移、发布与回滚 <a class="header-anchor" href="#版本迁移、发布与回滚" aria-label="Permalink to &quot;版本迁移、发布与回滚&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 发布不只是替换应用镜像。一次变更可能同时涉及 API、数据库、Checkpoint State、Prompt、工具 Schema、模型、Adapter、索引和评测标准。只有显式管理这些版本之间的兼容关系，回滚才不会在旧代码读到新数据时失败。</p><h2 id="_1-版本对象" tabindex="-1">1. 版本对象 <a class="header-anchor" href="#_1-版本对象" aria-label="Permalink to &quot;1. 版本对象&quot;">​</a></h2><h3 id="_1-1-应用与-api" tabindex="-1">1.1 应用与 API <a class="header-anchor" href="#_1-1-应用与-api" aria-label="Permalink to &quot;1.1 应用与 API&quot;">​</a></h3><p>应用制品用不可变 Commit/镜像 Digest 标识；公开 API 和事件契约按兼容性版本管理。SemVer 可表达发布意图，但不能自动证明消费者兼容。</p><h3 id="_1-2-数据-schema" tabindex="-1">1.2 数据 Schema <a class="header-anchor" href="#_1-2-数据-schema" aria-label="Permalink to &quot;1.2 数据 Schema&quot;">​</a></h3><p>业务数据库、队列消息、缓存值和对象格式都有 Schema。迁移需支持发布窗口内新旧代码并存。</p><h3 id="_1-3-agent-state-与-checkpoint" tabindex="-1">1.3 Agent State 与 Checkpoint <a class="header-anchor" href="#_1-3-agent-state-与-checkpoint" aria-label="Permalink to &quot;1.3 Agent State 与 Checkpoint&quot;">​</a></h3><p>工作流 State 字段、节点名称、路由语义和序列化格式变化会影响暂停中的 Thread。删除节点或改变状态含义可能使旧 Checkpoint 无法恢复。</p><h3 id="_1-4-prompt、工具与模型" tabindex="-1">1.4 Prompt、工具与模型 <a class="header-anchor" href="#_1-4-prompt、工具与模型" aria-label="Permalink to &quot;1.4 Prompt、工具与模型&quot;">​</a></h3><p>Prompt、工具 Schema、Chat Template、逻辑模型路由、基础模型/Adapter 和采样参数都是行为版本。它们变化即使不改代码，也要触发评测和发布记录。</p><h3 id="_1-5-rag-数据" tabindex="-1">1.5 RAG 数据 <a class="header-anchor" href="#_1-5-rag-数据" aria-label="Permalink to &quot;1.5 RAG 数据&quot;">​</a></h3><p>文档快照、切分器、Embedding 模型、索引和检索配置共同定义索引版本。新旧索引并存时，运行必须记录实际读取版本。</p><h2 id="_2-发布清单" tabindex="-1">2. 发布清单 <a class="header-anchor" href="#_2-发布清单" aria-label="Permalink to &quot;2. 发布清单&quot;">​</a></h2><p>一个不可变 Release Manifest：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">release_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agent-support-2026.07.31.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image_digest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sha256:...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">api_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">database_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">workflow_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">support-18</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">state_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prompt_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">support-23</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tool_catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model_route_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">index_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kb-2026-07-30</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">evaluation_run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eval-8f2c</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Manifest 绑定实际组合，而不是只列“使用最新版”。发布、Trace 和事故记录都引用 <code>release_id</code>。</p><h2 id="_3-兼容性模型" tabindex="-1">3. 兼容性模型 <a class="header-anchor" href="#_3-兼容性模型" aria-label="Permalink to &quot;3. 兼容性模型&quot;">​</a></h2><h3 id="_3-1-backward-与-forward" tabindex="-1">3.1 Backward 与 Forward <a class="header-anchor" href="#_3-1-backward-与-forward" aria-label="Permalink to &quot;3.1 Backward 与 Forward&quot;">​</a></h3><p>向后兼容通常指新消费者可读旧数据；向前兼容指旧消费者可容忍新数据。滚动发布期间两者可能都需要。</p><h3 id="_3-2-宽读严写" tabindex="-1">3.2 宽读严写 <a class="header-anchor" href="#_3-2-宽读严写" aria-label="Permalink to &quot;3.2 宽读严写&quot;">​</a></h3><p>消费者在支持范围内读取多个版本，生产者只写明确当前版本。无限期兼容会积累复杂度，因此需要迁移完成和删除旧路径的时间点。</p><h3 id="_3-3-未知字段与枚举" tabindex="-1">3.3 未知字段与枚举 <a class="header-anchor" href="#_3-3-未知字段与枚举" aria-label="Permalink to &quot;3.3 未知字段与枚举&quot;">​</a></h3><p>新增可选字段通常较安全；新增枚举值可能破坏穷举消费者。契约测试要覆盖真实消费者行为，而不仅是 Schema Diff。</p><h3 id="_3-4-语义兼容" tabindex="-1">3.4 语义兼容 <a class="header-anchor" href="#_3-4-语义兼容" aria-label="Permalink to &quot;3.4 语义兼容&quot;">​</a></h3><p>字段类型不变但单位、默认值或含义改变仍是破坏性变更。版本说明必须记录语义，不可只看 JSON 形状。</p><h2 id="_4-扩展-迁移-收缩" tabindex="-1">4. 扩展-迁移-收缩 <a class="header-anchor" href="#_4-扩展-迁移-收缩" aria-label="Permalink to &quot;4. 扩展-迁移-收缩&quot;">​</a></h2><h3 id="_4-1-expand" tabindex="-1">4.1 Expand <a class="header-anchor" href="#_4-1-expand" aria-label="Permalink to &quot;4.1 Expand&quot;">​</a></h3><p>先增加新字段、表、索引或消费者能力，保持旧路径可用。数据库迁移避免在高流量表直接执行长时间阻塞操作，具体策略按数据库版本验证。</p><h3 id="_4-2-migrate" tabindex="-1">4.2 Migrate <a class="header-anchor" href="#_4-2-migrate" aria-label="Permalink to &quot;4.2 Migrate&quot;">​</a></h3><p>新代码双读/双写或后台回填，监控覆盖率和差异。双写不是事务一致性的自动保证，需要明确权威源、失败修复和幂等。</p><h3 id="_4-3-contract" tabindex="-1">4.3 Contract <a class="header-anchor" href="#_4-3-contract" aria-label="Permalink to &quot;4.3 Contract&quot;">​</a></h3><p>确认所有生产者/消费者、暂停任务和回滚窗口不再依赖旧结构后，删除旧字段和兼容代码。收缩是独立发布，不与首次写新格式同时执行。</p><h2 id="_5-checkpoint-与工作流迁移" tabindex="-1">5. Checkpoint 与工作流迁移 <a class="header-anchor" href="#_5-checkpoint-与工作流迁移" aria-label="Permalink to &quot;5. Checkpoint 与工作流迁移&quot;">​</a></h2><h3 id="_5-1-运行中版本固定" tabindex="-1">5.1 运行中版本固定 <a class="header-anchor" href="#_5-1-运行中版本固定" aria-label="Permalink to &quot;5.1 运行中版本固定&quot;">​</a></h3><p>长任务可固定在启动时的 Workflow Version，直到完成；新任务进入新版本。这样最容易解释，但需要旧执行器在迁移期继续运行。</p><h3 id="_5-2-迁移状态" tabindex="-1">5.2 迁移状态 <a class="header-anchor" href="#_5-2-迁移状态" aria-label="Permalink to &quot;5.2 迁移状态&quot;">​</a></h3><p>若必须把旧 Thread 迁到新图，编写显式纯函数 <code>vN -&gt; vN+1</code>，保留原 Checkpoint，验证字段、不变量和下一节点。不要让新代码猜测缺失字段。</p><h3 id="_5-3-不可迁移任务" tabindex="-1">5.3 不可迁移任务 <a class="header-anchor" href="#_5-3-不可迁移任务" aria-label="Permalink to &quot;5.3 不可迁移任务&quot;">​</a></h3><p>定义取消、人工处理、补偿或继续旧版本的策略。静默重头执行可能重复外部副作用。</p><h2 id="_6-prompt、模型与索引发布" tabindex="-1">6. Prompt、模型与索引发布 <a class="header-anchor" href="#_6-prompt、模型与索引发布" aria-label="Permalink to &quot;6. Prompt、模型与索引发布&quot;">​</a></h2><h3 id="_6-1-行为变更" tabindex="-1">6.1 行为变更 <a class="header-anchor" href="#_6-1-行为变更" aria-label="Permalink to &quot;6.1 行为变更&quot;">​</a></h3><p>Prompt 或模型变化没有编译错误保护，必须通过版本化数据集、工具轨迹、安全、延迟和成本门禁。</p><h3 id="_6-2-索引切换" tabindex="-1">6.2 索引切换 <a class="header-anchor" href="#_6-2-索引切换" aria-label="Permalink to &quot;6.2 索引切换&quot;">​</a></h3><p>在新版本独立构建、校验文档数/权限/召回后，用别名或路由原子切换。保留旧索引直到回滚窗口结束；增量更新期间记录水位。</p><h3 id="_6-3-adapter-组合" tabindex="-1">6.3 Adapter 组合 <a class="header-anchor" href="#_6-3-adapter-组合" aria-label="Permalink to &quot;6.3 Adapter 组合&quot;">​</a></h3><p>基础模型、Adapter、Tokenizer、Chat Template 与推理引擎作为整体发布。只回滚 Adapter 可能仍与新模板不兼容。</p><h2 id="_7-发布策略" tabindex="-1">7. 发布策略 <a class="header-anchor" href="#_7-发布策略" aria-label="Permalink to &quot;7. 发布策略&quot;">​</a></h2><h3 id="_7-1-rolling" tabindex="-1">7.1 Rolling <a class="header-anchor" href="#_7-1-rolling" aria-label="Permalink to &quot;7.1 Rolling&quot;">​</a></h3><p>逐步替换实例，资源效率高，但新旧版本同时服务，要求双向兼容。适合常规低风险发布。</p><h3 id="_7-2-blue-green" tabindex="-1">7.2 Blue-Green <a class="header-anchor" href="#_7-2-blue-green" aria-label="Permalink to &quot;7.2 Blue-Green&quot;">​</a></h3><p>准备完整新环境后切换，回退快但需要额外容量。数据库和外部副作用仍是共享状态，切回流量不等于回滚数据。</p><h3 id="_7-3-canary" tabindex="-1">7.3 Canary <a class="header-anchor" href="#_7-3-canary" aria-label="Permalink to &quot;7.3 Canary&quot;">​</a></h3><p>少量稳定分组流量进入候选，按质量、错误、延迟、成本和安全门禁逐级扩大。多轮会话应保持版本粘性。</p><h3 id="_7-4-shadow" tabindex="-1">7.4 Shadow <a class="header-anchor" href="#_7-4-shadow" aria-label="Permalink to &quot;7.4 Shadow&quot;">​</a></h3><p>复制读流量给候选但不影响用户。候选必须禁用或隔离写副作用，并处理额外数据使用与费用。</p><h2 id="_8-回滚语义" tabindex="-1">8. 回滚语义 <a class="header-anchor" href="#_8-回滚语义" aria-label="Permalink to &quot;8. 回滚语义&quot;">​</a></h2><h3 id="_8-1-代码回滚" tabindex="-1">8.1 代码回滚 <a class="header-anchor" href="#_8-1-代码回滚" aria-label="Permalink to &quot;8.1 代码回滚&quot;">​</a></h3><p>重新部署上一不可变 Manifest，而不是从主分支临时重建。制品和配置都需可用。</p><h3 id="_8-2-数据回滚" tabindex="-1">8.2 数据回滚 <a class="header-anchor" href="#_8-2-数据回滚" aria-label="Permalink to &quot;8.2 数据回滚&quot;">​</a></h3><p>已写入的新数据通常不应直接逆迁移。优先让旧代码兼容新字段，或前滚修复。破坏性数据操作需备份、恢复点和业务补偿。</p><h3 id="_8-3-外部副作用" tabindex="-1">8.3 外部副作用 <a class="header-anchor" href="#_8-3-外部副作用" aria-label="Permalink to &quot;8.3 外部副作用&quot;">​</a></h3><p>发送的邮件、付款和删除不会因应用回滚自动撤销。记录操作 ID，执行独立补偿或人工流程。</p><h3 id="_8-4-模型与索引" tabindex="-1">8.4 模型与索引 <a class="header-anchor" href="#_8-4-模型与索引" aria-label="Permalink to &quot;8.4 模型与索引&quot;">​</a></h3><p>恢复旧路由/索引较快，但候选产生的记忆、缓存和业务结果可能继续存在，需要明确隔离、失效或重新评估。</p><h2 id="_9-自动门禁" tabindex="-1">9. 自动门禁 <a class="header-anchor" href="#_9-自动门禁" aria-label="Permalink to &quot;9. 自动门禁&quot;">​</a></h2><p>发布前验证单元/契约/集成、离线评测、安全、迁移 Dry Run、性能和制品扫描；发布中验证 Readiness、关键合成请求、SLO 燃烧、质量代理、成本和高风险工具；发布后保留观察窗口和旧制品。</p><p>自动停止阈值在发布前定义。没有最低流量和观察时间的百分比告警容易误判，严重安全事件可设置零容忍立即停止。</p><h2 id="_10-迁移与回滚演练" tabindex="-1">10. 迁移与回滚演练 <a class="header-anchor" href="#_10-迁移与回滚演练" aria-label="Permalink to &quot;10. 迁移与回滚演练&quot;">​</a></h2><ul><li>从生产规模快照估算迁移时长和锁影响；</li><li>新旧版本混部执行契约测试；</li><li>恢复旧 Checkpoint 和新迁移 Checkpoint；</li><li>切换索引并回切，验证缓存与权限；</li><li>发布中断、单副本失败和控制面不可用；</li><li>实际部署上一 Manifest，验证恢复时间。</li></ul><p>演练必须保留时间、结果和失败证据。只写 Runbook 不等于能够回滚。</p><h2 id="_11-常见误区" tabindex="-1">11. 常见误区 <a class="header-anchor" href="#_11-常见误区" aria-label="Permalink to &quot;11. 常见误区&quot;">​</a></h2><ol><li><strong>回滚镜像就回到旧系统</strong>：数据、Prompt、模型和索引可能已经变化。</li><li><strong>Schema 新增字段永远兼容</strong>：旧消费者可能拒绝未知字段或枚举。</li><li><strong>数据库 Down Migration 是首选回滚</strong>：可能丢失新数据或长时间锁表。</li><li><strong>Canary 只看错误率</strong>：质量与成本退化可能没有异常。</li><li><strong>所有会话立即切新工作流</strong>：暂停任务可能无法恢复或重复副作用。</li></ol><h2 id="_12-验收清单" tabindex="-1">12. 验收清单 <a class="header-anchor" href="#_12-验收清单" aria-label="Permalink to &quot;12. 验收清单&quot;">​</a></h2><ul><li>所有行为和数据版本是否进入 Release Manifest；</li><li>滚动窗口内新旧生产者/消费者是否兼容；</li><li>迁移是否按扩展、迁移、收缩分阶段；</li><li>运行中 Workflow/Checkpoint 是否有固定或迁移策略；</li><li>Canary 是否覆盖质量、安全、延迟和成本；</li><li>代码、数据、外部副作用和索引的回滚是否分别定义；</li><li>上一不可变制品是否实际演练过恢复。</li></ul><p>可回滚发布的本质不是保留旧镜像，而是在变更前设计兼容窗口和状态处理。能精确重建版本组合、限制候选影响并处理已产生副作用，才是真正的发布控制。</p>`,77)])])}const b=e(r,[["render",n]]);export{k as __pageData,b as default};
